export const oct13BlogSlugs=new Set(oct13BlogPosts.map(x=>x.slug));
export function getOct13BlogMetadata(slug:string){const a=articles[slug as keyof typeof articles];if(!a)return {};const canonical=`${site}/blog/${slug}`;return {title:a.title,description:a.excerpt,alternates:{canonical},openGraph:{title:a.title,description:a.excerpt,type:'article' as const,url:canonical,images:[a.image],publishedTime:published}}}
export function renderOct13BlogArticle(slug:string){const a=articles[slug as keyof typeof articles],canonical=`${site}/blog/${slug}`,related=oct13BlogPosts.filter(x=>x.slug!==slug).slice(0,3),schema={'@context':'https://schema.org','@type':'Article',headline:a.title,description:a.excerpt,datePublished:published,dateModified:published,mainEntityOfPage:canonical,image:site+a.image,author:{'@type':'Organization',name:'Outsourced Labor',url:site},publisher:{'@type':'Organization',name:'Outsourced Labor',url:site},citation:a.sources.map(x=>x.url)};return <><Header/><main className="article-page"><JsonLd data={schema}/><article className="container article-shell"><header className="article-header"><p className="eyebrow">Philippines workforce operations guide</p><h1>{a.title}</h1><p className="lead">{a.excerpt}</p><div className="article-meta"><span>12 min read</span><time dateTime={published}>{visible}</time></div><img src={a.image} alt={a.title} width="1200" height="630"/></header><aside className="card"><h2>Bounded service handoff</h2><p>A specialist prepares evidence while authorized owners retain workforce, pay, legal, safety, access, and client decisions.</p><a href={`/services/${oct13Services[slug]}`}>Review the related service</a></aside><div className="article-body">{a.sections.map(section=><section key={section.heading}><h2>{section.heading}</h2>{section.paragraphs.map(p=><p key={p}>{p}</p>)}</section>)}</div><section className="source-list"><h2>Authoritative references</h2><ol>{a.sources.map(source=><li key={source.url}><a href={source.url} target="_blank" rel="noreferrer">{source.name}</a> — {source.publisher}; checked {source.checked}</li>)}</ol></section><section><h2>Related October 13 guides</h2><ul>{related.map(item=><li key={item.slug}><a href={`/blog/${item.slug}`}>{item.title}</a></li>)}</ul></section></article><CTA/></main><Footer/></>}
